    adcs_vec3_t u, v;
    double norm1, norm2, dot, sep, cond;
    adcs_vec3_t cross_uv;

    if ((first == NULL) || (second == NULL) || (separation_rad == NULL) || (conditioning == NULL)) {
        return ADCS_E_NULL;
    }

    if (!adcs_is_finite_vec3(first) || !adcs_is_finite_vec3(second)) {
        return ADCS_E_NOT_FINITE;
    }

    norm1 = adcs_vec3_norm(first);
    norm2 = adcs_vec3_norm(second);

    if (norm1 <= ADCS_EPS_NORM || norm2 <= ADCS_EPS_NORM) {
        *separation_rad = 0.0;
        *conditioning = 0.0;
        return ADCS_E_DEGENERATE;
    }

    u = adcs_vec3_scale(first, 1.0 / norm1);
    v = adcs_vec3_scale(second, 1.0 / norm2);

    dot = adcs_vec3_dot(&u, &v);
    if (dot < -1.0) {
        dot = -1.0;
    } else if (dot > 1.0) {
        dot = 1.0;
    }

    sep = acos(dot);

    cross_uv = adcs_vec3_cross(&u, &v);
    cond = adcs_vec3_norm(&cross_uv);

    *separation_rad = sep;
    *conditioning = cond;

    return ADCS_OK;
}

